SELECT

FROM sys_notice

  AND status = #{query.status}
  AND category_id = #{query.categoryId}
  AND min_visibility = #{query.minVisibility}
  AND is_top = #{query.isTop}

    AND title LIKE CONCAT('%', #{query.keyword}, '%')


ORDER BY is_top DESC, updated_at DESC, id DESC

